package com.adc.application.performance;

import com.adc.application.*;
import com.adc.domain.shared.*;
import com.adc.identity.IdentityGate;
import com.adc.infrastructure.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.json.JsonMapper;

@Service @Transactional(isolation=Isolation.READ_COMMITTED,rollbackFor=Exception.class)
public class CostEntryService implements ReceiptPolicy {
    public record Create(String clinic_id,String dentist_id,String appointment_id,String applied_treatment_id,String cost_type,String amount,String incurred_at,String description,String source_reference,String source_batch,String verification_reference){}
    public record Reverse(String incurred_at,String source_reference,String source_batch,String verification_reference,String reason){}
    private final AtomicCommandExecutor commands;private final IdentityGate gate;private final CostEntryStore store;private final Clock clock;private final AuditWriter audit;private static final JsonMapper JSON=JsonMapper.builder().build();
    public CostEntryService(AtomicCommandExecutor commands,IdentityGate gate,CostEntryStore store,Clock clock,AuditWriter audit){this.commands=commands;this.gate=gate;this.store=store;this.clock=clock;this.audit=audit;}
    private static Long id(String id){return id==null?null:BusinessValues.id(id);}
    private static String text(String value,int max){if(value==null || value.isBlank() || value.length()>max)throw new DomainFailure(422,"INVALID_COST_SOURCE");return value;}
    private Instant time(String value){try{var time=OffsetDateTime.parse(value).toInstant();if(time.isAfter(clock.instant()) || time.getNano()!=0)throw new IllegalArgumentException();return time;}catch(RuntimeException invalid){throw new DomainFailure(422,"INVALID_COST_TIME");}}
    private void access(IdentityGate.Identity actor,long clinic){gate.requireStaff(actor,"HEADQUARTERS","cost.verify",clinic);}
    private AtomicCommandExecutor.Result saved(long id,long clinic,String reason,String reference){return new AtomicCommandExecutor.Result(JSON.writeValueAsString(List.of("CostEntry:"+id)),JSON.writeValueAsString(Map.of("cost_entry_id",Long.toString(id))),200,"CostEntry",Long.toString(id),List.of(clinic),reason,reference);}
    private Map<String,Object> result(AtomicCommandExecutor.Command command,AtomicCommandExecutor.Result result){var actor=gate.authenticate(command.token(),command.client());authorize(actor,command.operation(),result.refs());return store.view(store.get(Long.parseLong(JSON.readTree(result.summary()).get("cost_entry_id").asText()),false));}
    public Map<String,Object> create(AtomicCommandExecutor.Command command,Create input)throws Exception{
        long clinic=BusinessValues.id(input.clinic_id());String source=text(input.source_reference(),100);text(input.source_batch(),60);text(input.verification_reference(),255);if(input.cost_type()==null || !Set.of("MEDICAL_SUPPLY","OPERATING").contains(input.cost_type()))throw new DomainFailure(422,"INVALID_COST_TYPE");BigDecimal amount;try{if(input.amount()==null || !input.amount().matches("[0-9]{1,12}\\.[0-9]{2}"))throw new IllegalArgumentException();amount=BusinessValues.money(input.amount());}catch(IllegalArgumentException invalid){throw new DomainFailure(422,"INVALID_COST_AMOUNT");}var incurred=time(input.incurred_at());Long dentist=id(input.dentist_id()),appointment=id(input.appointment_id()),applied=id(input.applied_treatment_id());if(input.cost_type().equals("MEDICAL_SUPPLY") && dentist==null)throw new DomainFailure(422,"MISSING_MEDICAL_DENTIST");String description=input.description();if(amount.signum()==0){text(description,255);var date=incurred.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate();var first=LocalDate.of(date.getYear(),((date.getMonthValue()-1)/3)*3+1,1);description="clinic="+clinic+";quarter=["+first+","+first.plusMonths(3)+");type="+input.cost_type()+";scope="+description;}if(description!=null && description.length()>255)throw new DomainFailure(422,"INVALID_COST_SOURCE");final String storedDescription=description;
        try{return result(command,commands.executeWithLocks(command,List.of(TransactionLocks.name("cost-source",source)),actor->access(actor,clinic),actor->{store.attribution(dentist,clinic,appointment,applied);long row=store.insert(dentist,clinic,appointment,applied,input.cost_type(),amount,incurred,storedDescription,source,input.source_batch(),clock.instant(),actor.subjectId(),null);return saved(row,clinic,null,input.verification_reference());}));}catch(org.springframework.dao.DuplicateKeyException conflict){throw new DomainFailure(409,"COST_SOURCE_EXISTS");}
    }
    public Map<String,Object> reverse(AtomicCommandExecutor.Command command,long original,Reverse input)throws Exception{
        String source=text(input.source_reference(),100);text(input.source_batch(),60);text(input.verification_reference(),255);text(input.reason(),255);var incurred=time(input.incurred_at());try{return result(command,commands.executeWithLocks(command,List.of(TransactionLocks.name("cost-source",source),TransactionLocks.name("cost-reversal",Long.toString(original))),actor->access(actor,store.get(original,false).clinic()),actor->{var old=store.get(original,true);access(actor,old.clinic());if(old.amount().signum()<=0 || old.reversal()!=null || store.reversed(original))throw new DomainFailure(409,"COST_ALREADY_REVERSED_OR_NOT_POSITIVE");long row=store.insert(old.dentist(),old.clinic(),old.appointment(),old.applied(),old.type(),old.amount().negate(),incurred,input.reason(),source,input.source_batch(),clock.instant(),actor.subjectId(),original);return saved(row,old.clinic(),input.reason(),input.verification_reference());}));}catch(org.springframework.dao.DuplicateKeyException conflict){throw new DomainFailure(409,"COST_SOURCE_OR_REVERSAL_EXISTS");}
    }
    public Map<String,Object> list(String token,String client,Long clinic,String start,String end,String cursor,int limit,String request){var failed=new IdentityGate.Identity[1];AuditWriter.onRollback(audit,()->failed[0],"listCostEntries",request);var actor=gate.authenticate(token,client);failed[0]=actor;var clinics=gate.staffClinics(actor,"HEADQUARTERS","cost.verify");if(clinic!=null){access(actor,clinic);clinics=List.of(clinic);}if(limit<1 || limit>100)throw new DomainFailure(400,"INVALID_REQUEST");var from=start==null?null:OffsetDateTime.parse(start).toInstant();var until=end==null?null:OffsetDateTime.parse(end).toInstant();if(from!=null && until!=null && !until.isAfter(from))throw new DomainFailure(422,"INVALID_PERIOD");var rows=store.list(clinics,from,until,cursor==null?null:BusinessValues.id(cursor),limit+1);var page=rows.stream().limit(limit).map(store::view).toList();var response=new LinkedHashMap<String,Object>();response.put("items",page);response.put("next_cursor",rows.size()>limit?Long.toString(rows.get(limit-1).id()):null);audit.success(actor,"listCostEntries","CostEntry",null,clinics,request);return response;}
    @Override @Transactional(propagation=Propagation.NOT_SUPPORTED)public Set<String> operations(){return Set.of("recordCostEntry","reverseCostEntry");}
    public Map<String,Object> get(String token,String client,long id,String request){var failed=new IdentityGate.Identity[1];AuditWriter.onRollback(audit,()->failed[0],"getCostEntry",request);var actor=gate.authenticate(token,client);failed[0]=actor;gate.staffClinics(actor,"HEADQUARTERS","cost.verify");var row=store.get(id,false);access(actor,row.clinic());audit.success(actor,"getCostEntry","CostEntry",Long.toString(id),List.of(row.clinic()),request);return store.view(row);}
    @Override public void authorize(IdentityGate.Identity actor,String operation,String refs){gate.staffClinics(actor,"HEADQUARTERS","cost.verify");if(refs!=null)for(var ref:JSON.readTree(refs)){String value=ref.asText();if(!value.startsWith("CostEntry:"))throw new DomainFailure(403,"ACCESS_DENIED");access(actor,store.get(Long.parseLong(value.substring(10)),false).clinic());}}
}
